// Run in an isolated agent-browser session: agent-browser eval --stdin < this-file
(async()=>{
const wait=()=>new Promise(r=>setTimeout(r,180)),check=(v,t)=>{if(!v)throw Error(t)};
const click=async(text,scope=document)=>{const el=[...scope.querySelectorAll('button')].find(e=>e.textContent.trim()===text);check(el,'missing '+text);el.click();await wait()};
const fill=async(name,value)=>{const el=document.querySelector(`input[name="${name}"]`);check(el,'input '+name);Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(el,value);el.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
location.hash='/overview';await wait();const shell=document.querySelector('.sidebar'),url=location.href,length=history.length;
await click('目标与 OKR',shell);check(location.href===url&&history.length===length,'sidebar changed URL/history');check(document.querySelector('.sidebar')===shell,'sidebar remounted');check(document.querySelector('.primary-nav .active').textContent.includes('工作台'),'sidebar changed area');check(document.querySelector('main').textContent.includes('目标'),'content did not switch');check(shell.querySelectorAll('a').length===0,'sidebar still contains route links');check(!document.querySelector('[aria-label="项目实例选择"]'),'redundant project list exists');
const compact=matchMedia('(max-width: 1023px)').matches;if(compact){document.querySelector('[aria-label="展开导航"]').click();await wait();}const selector=document.querySelector('[aria-label="项目实例"]');selector.click();await wait();check(!!document.querySelector('[role=listbox]'),'custom selector missing');await click('向海而生 · 品牌短片',document.querySelector('[role=listbox]'));check(location.href===url,'project changed route');check(document.activeElement===(compact?document.querySelector('[aria-label="展开导航"]'):selector),'select focus not restored to visible trigger');if(compact)check(!document.querySelector('.sidebar.open'),'project selection left mobile drawer open');
const originalWork=JSON.stringify(JSON.parse(localStorage.getItem('collaboration-prototype-v1')).work);
document.querySelector('.tenant-trigger').click();await wait();await click('创建租户');await click('创建并进入');check(!!document.querySelector('.field-error'),'custom validation missing');check(!!document.querySelector('form[novalidate]'),'browser validation not disabled');await fill('租户名称','浏览器隔离验收');await click('创建并进入');let state=JSON.parse(localStorage.getItem('collaboration-prototype-v1'));check(state.projects.length===0&&state.work.length===0,'new tenant inherited records');check(document.body.innerText.includes('从第一个项目实例开始'),'empty tenant welcome missing');
document.querySelector('.tenant-trigger').click();await wait();const studio=[...document.querySelectorAll('.tenant-popover>button')].find(x=>x.textContent.includes('Northstar Studio'));studio.click();await wait();state=JSON.parse(localStorage.getItem('collaboration-prototype-v1'));check(state.activeTenant==='studio'&&JSON.stringify(state.work)===originalWork,'tenant records not restored');
document.querySelector('[aria-label="切换主题"]').click();await wait();for(const name of ['Modern 简约','Business 商务','护眼纸感','Pink Kawaii','Neo Brutalism','Aurora 极光']){await click(name);check(document.querySelector('dialog[open]'),'theme modal disappeared');check(document.querySelector('meta[name=theme-color]').content.toLowerCase()===getComputedStyle(document.documentElement).getPropertyValue('--bg').trim().toLowerCase(),'browser theme color differs from selected palette')};check(getComputedStyle(document.documentElement).getPropertyValue('--primary').trim().toLowerCase()==='#7c3aed','source Aurora token changed');document.querySelector('dialog [aria-label="关闭弹窗"]').click();await wait();
location.hash='/machines/n1';await wait();await click('吊销节点');check(document.querySelector('dialog')?.textContent.includes('确认继续'),'custom confirmation missing');await click('取消');check(!document.querySelector('dialog[open]'),'cancel failed');
location.hash='/chat?channel_id=launch';await wait();const chatUrl=location.href,channels=document.querySelector('.channel-list');await click('协作总频道跨项目 · 组织范围',channels);check(location.href===chatUrl&&document.querySelector('.channel-list')===channels,'channel navigation changed route or shell');
return {pass:true,checks:['sidebar URL/history and shell stable','single project selector','custom dropdown focus','custom validation','tenant create/switch isolation','six source themes','custom destructive confirmation','channel switches in place']};
})()
